Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PECHU6B.
Import PMU. Import PECHU.
Local Ltac lia := PMK.alia.

Section Stage.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis SPB0 : 0 <= PESK.sp_B P.
Hypothesis PMODE : PESK.sp_mode P.
Let KL := PECKU.klayout_U L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ptr ra : Z).
Variable payload : list byte.
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 67584.
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Abbreviation hcore := (PECHU.hcore L R0 M0 model0 sp ra LB0).
Abbreviation vstr_at := (PM.vstr_at RSEGS PMSP.T3).
Abbreviation iss_at := (PM.iss_at RSEGS AD PMSP.T3).
Abbreviation enc_at := (PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4).
Abbreviation sink_at := (PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P).
Abbreviation G6b := (PECHU6.G6b L HI P R0 M0 model0 sp ra payload LB0 cr0 g).
(* [comment removed for export] *)
Definition G6c (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s s2 : PM.vstr) (sm : PM.strm) (k : PESK.sink) (be : bool) : Prop :=
  hcore R M model /\ getr R (reg 9) = Z_to_bv 64 (PECHU.fb sp + 456) /\ vstr_at M (PECHU.fb sp + 784) s /\ PM.vs_size s = PECHU.n payload
  /\ iss_at M (PECHU.fb sp + 512) s2 sm
  /\ sink_at M (PECHU.fb sp + 488) k
  /\ PECHU.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI (PESK.sink_own k ++ PM.vs_own s2 ++ PM.vs_own s ++ LB0) cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PECHU.P0 L P payload) (PESK.sink_pot P (PESK.sk_c k)).

Lemma estack_gone :
  PEUVD.estk_dtor_spec L HI ->
  forall (fx : FPState) R M model cr s s2 sm en k be K,
    G6b R M model cr s s2 sm en k be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        G6c R1 M1 model1 cr s s2 sm k be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x35000 M1 model1) K) ->
